function addFail(o:any, k:"identity"|"auth"|"recovery") {
  const f = k === "identity" ? "identityFailures" : k === "auth" ? "authFailures" : "recoveryFailures";
  const l = k === "identity" ? "identityLocked" : k === "auth" ? "authLocked" : "recoveryLocked";
