}
function clearFail(o:any, k:"identity"|"auth"|"recovery") { o[k === "identity" ? "identityFailures" : k === "auth" ? "authFailures" : "recoveryFailures"] = 0; }
function lock<T>(u:string, f:()=>Promise<T>) {
